public void populateCards(ABSWorkspaceCardData _cursor)
{
    ABSItemABCXYZ           abcXyzAgg;
    ABSItemABCXYZ           abcXyzNoHist;
    ABSItemABCXYZ           abcXyzJoin;
    InventSum               inventSumAgg;
    InventDim               inventDimJoin;
    int                     abcInt;
    int                     xyzInt;

    delete_from _cursor;

    for (abcInt = 1; abcInt <= 3; abcInt++)
    {
        for (xyzInt = 1; xyzInt <= 3; xyzInt++)
        {
            ABSABCClassification abcClass = abcInt;
            ABSXYZClassification xyzClass = xyzInt;

            select count(RecId), sum(SalesAmt12M) from abcXyzAgg
                where abcXyzAgg.ABCClass == abcClass
                   && abcXyzAgg.XYZClass == xyzClass;

            // W6: count items with no demand history (C/Z completeness-sweep defaults)
            // so the card can separate measured demand from sweep noise.
            select count(RecId) from abcXyzNoHist
                where abcXyzNoHist.ABCClass               == abcClass
                   && abcXyzNoHist.XYZClass               == xyzClass
                   && abcXyzNoHist.HistoryMonthsAvailable == 0;

            select sum(PostedValue) from inventSumAgg
                join inventDimJoin
                    where inventDimJoin.inventDimId == inventSumAgg.inventDimId
                exists join abcXyzJoin
                    where abcXyzJoin.ItemId   == inventSumAgg.ItemId
                       && abcXyzJoin.SiteId   == inventDimJoin.InventSiteId
                       && abcXyzJoin.ABCClass == abcClass
                       && abcXyzJoin.XYZClass == xyzClass;

            _cursor.ABCClass            = abcClass;
            _cursor.XYZClass            = xyzClass;
            _cursor.ItemCount           = any2Int(abcXyzAgg.RecId);
            _cursor.NoHistoryCount      = any2Int(abcXyzNoHist.RecId);
            _cursor.TotalConsumption12M = abcXyzAgg.SalesAmt12M;
            _cursor.TotalInventoryValue = inventSumAgg.PostedValue;
            _cursor.insert();
        }
    }
}

public display str ABCXYZLabel(ABSWorkspaceCardData _cardData)
{
    str abcDesc;
    str xyzDesc;

    switch (_cardData.ABCClass)
    {
        case ABSABCClassification::A:
            abcDesc = 'High';
            break;
        case ABSABCClassification::B:
            abcDesc = 'Medium';
            break;
        case ABSABCClassification::C:
            abcDesc = 'Low';
            break;
        default:
            abcDesc = '';
    }

    switch (_cardData.XYZClass)
    {
        case ABSXYZClassification::X:
            xyzDesc = 'stable';
            break;
        case ABSXYZClassification::Y:
            xyzDesc = 'variable';
            break;
        case ABSXYZClassification::Z:
            xyzDesc = 'irregular';
            break;
        default:
            xyzDesc = '';
    }

    return strFmt('%1%2 – %3, %4',
        enum2Str(_cardData.ABCClass),
        enum2Str(_cardData.XYZClass),
        abcDesc,
        xyzDesc);
}

/// W6: shows the segment item count and, when present, how many have no demand history.
public display str itemCountDisplay(ABSWorkspaceCardData _cardData)
{
    if (_cardData.NoHistoryCount > 0)
    {
        return strFmt('@ABS:ABSWorkspaceItemCountWithNoHistory', _cardData.ItemCount, _cardData.NoHistoryCount);
    }

    return int2str(_cardData.ItemCount);
}

public void displayOption(Common _record, FormRowDisplayOption _options)
{
    ABSWorkspaceCardData cardData = _record;
    int bgColor;

    // W4: empty segments recede (near-white) so the eye lands on populated cells.
    if (cardData.ItemCount == 0)
    {
        _options.backColor(ABSUIColors::muted());
        super(_record, _options);
        return;
    }

    // W2: colour by ABC class as an *importance* scale (cool A→C ramp),
    // NOT a green/red health judgement (AZ is not "good", CX is not "bad").
    switch (cardData.ABCClass)
    {
        case ABSABCClassification::A:
            bgColor = ABSUIColors::segmentA();
            break;
        case ABSABCClassification::B:
            bgColor = ABSUIColors::segmentB();
            break;
        case ABSABCClassification::C:
            bgColor = ABSUIColors::segmentC();
            break;
        default:
            super(_record, _options);
            return;
    }

    _options.backColor(bgColor);
    super(_record, _options);
}

/// W3: clicking a card drills down to ABSItemABCXYZ pre-filtered to that segment
/// (the per-segment display menu items ABSItemABCXYZ_AX..CZ), replacing the tile row.
public void jumpRef()
{
    MenuFunction menuFunction;
    str          menuItemName;

    menuItemName = strFmt('ABSItemABCXYZ_%1%2',
        enum2Str(ABSWorkspaceCardData.ABCClass),
        enum2Str(ABSWorkspaceCardData.XYZClass));

    menuFunction = new MenuFunction(menuItemName, MenuItemType::Display);
    menuFunction.run();
}
